INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Preiskalkulation immer nur kostenorientiert?', 2, '[{"text": "Nein", "correct": true, "because": "Marktorientierte oder wettbewerbsorientierte Ansätze existieren"}, {"text": "Ja", "correct": false, "because": "Mehrere Methoden möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel der Preiskalkulation?', 3, '[{"text": "Kostendeckung sichern", "correct": true, "because": "Gewährleistet Wirtschaftlichkeit"}, {"text": "Maximale Rabatte", "correct": false, "because": "Nicht primär"}, {"text": "Manuelle Preisfestlegung", "correct": false, "because": "Strukturierte Ansätze bevorzugt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Preiskalkulation?', 5, '[{"text": "Produktionskosten", "correct": true, "because": "Basis für Preis"}, {"text": "Marktnachfrage", "correct": true, "because": "Bestimmt Zahlungsbereitschaft"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant für Preis"}, {"text": "Bürogestaltung", "correct": false, "because": "Kein Preisfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Zuschlagskalkulation berücksichtigt Gemeinkosten. b) Preise ignorieren Wettbewerber.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Wettbewerb relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Preiskalkulation?', 4, '[{"text": "Kostenstruktur", "correct": false, "because": "Basis für Kalkulation"}, {"text": "Marktpreise", "correct": false, "because": "Bestimmen Wettbewerbsfähigkeit"}, {"text": "Musikwiedergabe", "correct": true, "because": "Irrelevant für Preis"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Zuschlagskalkulation Gemeinkosten berücksichtigt?', 2, '[{"text": "Ja", "correct": true, "because": "Verteilt Gemeinkosten auf Produkte"}, {"text": "Nein", "correct": false, "because": "Gemeinkosten enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode ist typisch für die Preiskalkulation?', 3, '[{"text": "Deckungsbeitragsrechnung", "correct": true, "because": "Ermittelt Profitabilität"}, {"text": "Zufallspreis", "correct": false, "because": "Kein strukturierter Ansatz"}, {"text": "Manuelle Schätzung", "correct": false, "because": "Unzuverlässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kostenarten fließen in die Kalkulation ein?', 5, '[{"text": "Fixkosten", "correct": true, "because": "Unabhängig von Produktion"}, {"text": "Variable Kosten", "correct": true, "because": "Produktionsabhängig"}, {"text": "Marketingkosten", "correct": false, "because": "Sekundär für Kalkulation"}, {"text": "Bürokosten", "correct": false, "because": "Teilweise relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Preiskalkulation berücksichtigt Wettbewerber. b) Sie garantiert Gewinne. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) hängt von Markt ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Preiskalkulation?', 4, '[{"text": "Kostenanalyse", "correct": false, "because": "Grundlage der Kalkulation"}, {"text": "Marktbeobachtung", "correct": false, "because": "Sichert Wettbewerbsfähigkeit"}, {"text": "3D-Modellierung", "correct": true, "because": "Irrelevant für Preis"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die marktorientierte Kalkulation von Kosten unabhängig?', 2, '[{"text": "Nein", "correct": true, "because": "Berücksichtigt Marktpreise"}, {"text": "Ja", "correct": false, "because": "Markt beeinflusst Preis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ansätze gibt es für die Preiskalkulation?', 4, '[{"text": "Kostenorientiert", "correct": true, "because": "Basiert auf Kosten"}, {"text": "Wettbewerbsorientiert", "correct": true, "because": "Berücksichtigt Konkurrenz"}, {"text": "Zufallsorientiert", "correct": false, "because": "Kein Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Preiskalkulation immer einfach ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Komplex durch viele Faktoren"}, {"text": "Ja", "correct": false, "because": "Erfordert Analyse"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Preiskalkulation?', 3, '[{"text": "Kostendeckung", "correct": true, "because": "Sichert Rentabilität"}, {"text": "Maximaler Preis", "correct": false, "because": "Markt begrenzt"}, {"text": "Manuelle Schätzung", "correct": false, "because": "Strukturierte Methoden besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Deckungsbeitragsrechnung zeigt Profitabilität. b) Preise ignorieren Nachfrage.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) berücksichtigt Nachfrage"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Preiskalkulation?', 5, '[{"text": "Wettbewerbsfähigkeit", "correct": true, "because": "Passt Preis an Markt"}, {"text": "Gewinnoptimierung", "correct": true, "because": "Balanciert Kosten"}, {"text": "Hohe Komplexität", "correct": false, "because": "Eher Nachteil"}, {"text": "Einheitliche Preise", "correct": false, "because": "Marktabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Preiskalkulation unwichtig?', 3, '[{"text": "Kostenstruktur", "correct": false, "because": "Grundlage für Preis"}, {"text": "Kundenzufriedenheit", "correct": false, "because": "Beeinflusst Nachfrage"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Preisfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Preiskalkulation für Dienstleistungen anders ist?', 2, '[{"text": "Ja", "correct": true, "because": "Arbeitszeit oft zentral"}, {"text": "Nein", "correct": false, "because": "Unterschiedliche Faktoren"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Berücksichtigt die Zuschlagskalkulation Fixkosten?', 3, '[{"text": "Ja", "correct": true, "because": "Verteilt Fixkosten auf Einheiten"}, {"text": "Nein", "correct": false, "because": "Fixkosten enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zur Preiskalkulation?', 4, '[{"text": "Festlegung eines Softwarepreises", "correct": true, "because": "Berücksichtigt Kosten und Markt"}, {"text": "Erstellung eines Logos", "correct": false, "because": "Kreative Aufgabe"}, {"text": "Netzwerkwartung", "correct": false, "because": "Technische Aufgabe"}]');
